\title{Packing-Isolating Sets in Block Graphs:\\
Existence on Extremal Families and the Sharpness of the Block-Graph Hypothesis}
\author{Aristotle}
\date{June 21, 2026}

\begin{document}
\maketitle

\begin{abstract}
A \emph{packing-isolating set} of a finite simple graph $G$ is a vertex set $S$
that is simultaneously a \emph{2-packing}---the closed neighborhoods of distinct
vertices of $S$ are pairwise disjoint---and an \emph{isolating set}---every edge
of $G$ has at least one endpoint in the closed neighborhood $\Nbr{S}$ of $S$.
These two requirements are antagonistic: the packing condition forces the chosen
vertices to be mutually far apart, while the isolating condition forces them to
be collectively dense enough to dominate every edge. We study the conjecture that
\emph{every finite block graph admits a packing-isolating set}, where a block
graph is a graph each of whose blocks (maximal $2$-connected subgraphs) is a
clique. We establish the conjecture constructively on the two structurally
extremal families of block graphs. For complete graphs $K_{n+1}$ we show that any
single vertex is packing-isolating. For path graphs $P_n$ we show that the
residue class $S = \{\, i : i \equiv 1 \pmod 3 \,\}$ is packing-isolating for
every $n$, and we analyze why this \emph{aligned periodic} set succeeds where a
greedy maximal packing fails. Finally we prove sharpness: the five-cycle $C_5$,
the smallest non-block graph that could cause trouble, admits \textbf{no}
packing-isolating set, certified by an exhaustive search over all $2^5$ vertex
subsets. The $C_5$ obstruction decomposes cleanly into ``diameter two suppresses
large packings'' and ``no dominating vertex suppresses small isolating sets,''
and we contrast it with $C_4$, which does admit one, isolating the role of the
odd cycle. All results are machine-verified.
\end{abstract}

\section{Introduction}

\subsection{Motivation}
Many resource-placement problems in networked systems balance two opposing
desiderata. On the one hand, chosen sites should be \emph{mutually
non-interfering}---spread far enough apart that their spheres of influence do not
overlap. On the other hand, the chosen sites should \emph{collectively cover} the
entire structure---every connection should fall within reach of some site. In
wireless network design this is the tension between interference avoidance and
link coverage; in sentinel surveillance it is the tension between statistically
independent monitors and complete observability; in distributed systems it is
independence versus domination.

The combinatorial distillation of this tension pairs two classical notions. A
\emph{2-packing} (a maximally spread-out, mutually non-overlapping family of
closed neighborhoods) encodes non-interference. An \emph{isolating set} (a set
whose closed neighborhood meets every edge) encodes coverage. A set that is both
at once we call a \textbf{packing-isolating set}. The natural question is which
graphs possess one.

\subsection{Block graphs and the central conjecture}
A \textbf{block} of a graph $G$ is a maximal connected subgraph with no cut
vertex---equivalently a maximal $2$-connected subgraph or a bridge edge. $G$ is a
\textbf{block graph} if every block is a clique. Block graphs are precisely the
graphs realizable as ``trees of cliques.'' Trees (every block is an edge $K_2$)
and complete graphs (a single clique block) are the extreme members.

\begin{quote}
\textbf{Conjecture (Block-graph packing-isolation).} Every finite block graph
$G$ admits a packing-isolating set $S$.
\end{quote}

This paper makes three contributions delineating the conjecture's content:
(1) complete graphs admit packing-isolating sets (any single vertex works);
(2) path graphs admit packing-isolating sets via an explicit period-three
residue construction valid for all $n$; and (3) the block-graph hypothesis is
sharp---the five-cycle $C_5$ admits no packing-isolating set and is the minimal
non-block graph exhibiting this failure.

\section{Definitions}
Throughout, $G=(V,E)$ is a finite simple graph with adjacency $u \sim v$, and
$\Fin\,n = \{0,1,\dots,n-1\}$.

\begin{definition}[Closed neighborhood]
For a vertex $v$, $\Nbr{v} = \{v\} \cup \{\, u : u \sim v \,\}$.
\end{definition}

\begin{definition}[Neighborhood of a set]
For a vertex set $S$, $\Nbr{S} = \bigcup_{v\in S} \Nbr{v}$.
\end{definition}

\begin{definition}[2-packing]
$S$ is a \emph{2-packing} if for all distinct $u,v \in S$,
$\Nbr{u} \cap \Nbr{v} = \varnothing$; equivalently every pair of distinct
vertices of $S$ is at distance at least $3$.
\end{definition}

\begin{definition}[Isolating set]
$S$ is \emph{isolating} if every edge has an endpoint in $\Nbr{S}$: for all
$u \sim v$, $u \in \Nbr{S}$ or $v \in \Nbr{S}$.
\end{definition}

\begin{definition}[Packing-isolating set]
$S$ is \emph{packing-isolating} if it is both a 2-packing and isolating.
\end{definition}

\begin{definition}[Dominating set]
$S$ \emph{dominates} $G$ if $\Nbr{S} = V$. A dominating set is automatically
isolating, since both endpoints of every edge already lie in $\Nbr{S}$.
\end{definition}

\begin{definition}[Path graph]
$P_n$ has vertex set $\Fin\,n$ with $i \sim j$ iff $i+1=j \vee j+1=i$.
\end{definition}

\begin{definition}[Five-cycle]
$C_5$ has vertex set $\Fin\,5$ with $i \sim j$ iff $(i+1)\bmod 5 = j \vee
(j+1)\bmod 5 = i$.
\end{definition}

\section{The Upper Extreme: Complete Graphs}

\begin{theorem}[\texttt{completeGraph\_packingIsolating}]
For every vertex $v \in K_{n+1}$, the singleton $\{v\}$ is packing-isolating.
\end{theorem}

\begin{proof}[Proof sketch]
A singleton is vacuously a 2-packing. For isolation we prove the stronger claim
that $\{v\}$ \emph{dominates} $K_{n+1}$ and apply
\texttt{isIsolating\_of\_dominating}. Given any $x$, either $x=v$ (so $x \in
\Nbr{v}$ as the center) or $x \neq v$, in which case $x \sim v$ since every pair
of distinct vertices is adjacent in a complete graph. Hence $\Nbr{\{v\}} = V$,
every edge has both endpoints in $\Nbr{\{v\}}$, and $\{v\}$ is isolating.
\end{proof}

\begin{corollary}[\texttt{completeGraph\_exists\_packingIsolating}]
For every $n$, $K_{n+1}$ admits a packing-isolating set, namely $\{0\}$.
\end{corollary}

\section{The Lower Extreme: Path Graphs}

\subsection{The construction}
\begin{definition}[\texttt{pathPacking}]
$S_n = \{\, i \in \Fin\,n : i \equiv 1 \pmod 3 \,\} = \{1,4,7,\dots\}$.
\end{definition}

On a path the closed-neighborhood membership is
$x \in \Nbr{v} \iff x=v \vee x+1=v \vee v+1=x$, i.e.\ $x$ is within distance one
of $v$. Combined with the definition of $\Nbr{S}$ this gives the working
description: $x \in \Nbr{S_n}$ iff there exists $s \equiv 1 \pmod 3$ with $x=s$,
$x+1=s$, or $s+1=x$.

\subsection{The packing property}
\begin{theorem}[\texttt{pathG\_twoPacking}]
For every $n$, $S_n$ is a 2-packing of $P_n$.
\end{theorem}
\begin{proof}[Proof sketch]
Let $u,v \in S_n$ be distinct, so $u \equiv v \equiv 1 \pmod 3$ and $u \neq v$.
If some $x$ lay in both $\Nbr{u}$ and $\Nbr{v}$ then $|u-v| \le 2$; but two
distinct integers congruent to $1$ modulo $3$ differ by at least $3$, a
contradiction. Hence $\Nbr{u} \cap \Nbr{v} = \varnothing$.
\end{proof}

\subsection{The isolating property}
\begin{theorem}[\texttt{pathG\_isolating}]
For every $n$, $S_n$ is isolating in $P_n$.
\end{theorem}
\begin{proof}[Proof sketch]
Every edge joins consecutive vertices $a,a+1$. Split on $a \bmod 3$:
if $a \equiv 0$ then $a+1 \in S_n$; if $a \equiv 1$ then $a \in S_n$; if
$a \equiv 2$ then $a-1 \in S_n$ and $a \in \Nbr{a-1}$. In each case the edge is
covered.
\end{proof}

\begin{remark}[The backward witness]
The residue-$2$ case is the crux: the covering vertex $s=a-1$ sits \emph{behind}
the edge. A forward-only scheme fails at the right endpoint, which is the formal
reason the construction must be a phased periodic set rather than any maximal
packing.
\end{remark}

\subsection{The combined result}
\begin{theorem}[\texttt{pathG\_packingIsolating}]
For every $n$, $S_n$ is packing-isolating in $P_n$.
\end{theorem}
\begin{proof}
Immediate from the previous two theorems.
\end{proof}

\begin{corollary}[\texttt{pathG\_exists\_packingIsolating}]
Every path graph $P_n$ admits a packing-isolating set.
\end{corollary}

\subsection{Alignment versus maximality}
A maximal 2-packing need not be isolating. In $P_6$ the endpoints $\{0,5\}$ form
a maximal 2-packing (distance $5 \ge 3$, no third vertex addable), yet the edge
$\{2,3\}$ is uncovered: $\Nbr{0}=\{0,1\}$, $\Nbr{5}=\{4,5\}$. The aligned set
$S_6=\{1,4\}$ covers every edge. Existence is a statement about a particular
aligned construction, not about extremal packings.

\section{Sharpness: The Five-Cycle Obstruction}

\begin{theorem}[\texttt{C5\_no\_packingIsolating}]
No vertex set of the five-cycle $C_5$ is packing-isolating.
\end{theorem}
\begin{proof}
Packing-isolation is a decidable predicate over the $2^5=32$ subsets of a
five-element vertex set. An exhaustive finite check verifies that none of the
$32$ candidate sets satisfies both conditions.
\end{proof}

\begin{corollary}[\texttt{C5\_not\_packingIsolating\_exists}]
There is no $S$ with $\mathrm{IsPackingIsolating}(C_5,S)$; the conjecture's
conclusion fails for the concrete non-block graph $C_5$.
\end{corollary}

\subsection{Structural explanation}
\textbf{The packing side forces $|S|\le 1$.} $C_5$ has diameter $2$, so any two
distinct vertices are at distance $\le 2$, incompatible with the distance-$\ge 3$
packing requirement; a 2-packing has at most one vertex.

\textbf{The isolating side forces $|S|\ge 2$.} A single vertex $v$ has
$\Nbr{v}=\{v,v-1,v+1\}$, missing the two far vertices and the edge between them;
no singleton (and not the empty set) is isolating. The two bounds collide, so no
set works.

\subsection{Odd cycle, not ``having a cycle''}
The square $C_4$ \emph{does} admit a packing-isolating set: one corner reaches
three corners and meets every edge, and being a singleton it is trivially a
2-packing. The failure is specific to the odd five-cycle---diameter two combined
with no single dominating vertex---a deadlock the clique-block hypothesis
excludes.

\section{Algorithms}
\paragraph{Decision by exhaustive search.} For $|V|=m$, checking a fixed $S$
costs $O(|S|^2\Delta + |E|)$ and searching all subsets costs $O(2^m)$ checks;
feasible only for small $m$, used as a boundary certificate (e.g.\ $m=5$).

\paragraph{Periodic construction on paths.} For $P_n$, $S_n$ is built in one
$O(n)$ pass; both conditions verify by a single linear scan, giving total $O(n)$
time and output size $O(n/3)$.

\section{Applications and Interpretation}
The packing condition models non-interfering transmitters or
quasi-independent monitors; the isolating condition models complete link
coverage or observability. On tree-of-cliques topologies the constructions give
explicit placements. Because block graphs arise as random tree-of-cliques
models, the existence question has a probabilistic dimension: thresholds and
typical minimum sizes of packing-isolating sets in random block graphs, for
which the deterministic extremal results here serve as calibration.

\section{Discussion and Future Work}
\begin{enumerate}
\item \textbf{Full conjecture via block-cut induction.} Peel leaf blocks of the
tree of cliques; the path backward-witness phenomenon is the bookkeeping for
whether the cut vertex is ``spent.''
\item \textbf{Sharp lower bound for paths.} Conjecturally the minimum
packing-isolating set of $P_n$ has size $\lceil n/3 \rceil$ for $n \ge 2$.
\item \textbf{Small obstructions.} Conjecturally any graph with no
packing-isolating set contains an induced odd hole or diameter-$\le 2$ subgraph
with no dominating vertex, $C_5$ minimal.
\item \textbf{Clique-amalgamation closure.} Packing-isolating sets should compose
across a single shared cut vertex.
\item \textbf{Probabilistic thresholds} in random block graphs.
\end{enumerate}

\section{Conclusion}
Packing-isolating sets exist on both structural extremes of the block-graph
family: trivially on complete graphs and via an explicit phased period-three
construction on paths. The block-graph hypothesis is sharp---$C_5$ admits none,
its failure a collision between a diameter-two packing ceiling and a
no-dominating-vertex isolating floor, a deadlock the clique-block structure
forbids and the even cycle $C_4$ escapes.

\end{document}

