function FIND-PACKING-ISOLATING(G = (V, E)):
    for r = 0 to |V|:
        for each subset S of V with |S| = r:
            if IS-TWO-PACKING(G, S) and IS-ISOLATING(G, S):
                return S
    return NONE

function IS-TWO-PACKING(G, S):
    for each unordered pair {u, v} in S:
        if N[u] intersect N[v] is nonempty: return false
    return true

function IS-ISOLATING(G, S):
    cover := union of N[v] for v in S
    for each edge {u, w} in E:
        if u not in cover and w not in cover: return false
    return true

